// CSD_RATIONALE_BEGIN
// This strategy keeps the prior structure: free generation outside spans,
// explicit visible `<< >>` arithmetic spans, and parser-controlled decoding
// inside spans. The concrete verification failure came from using a helper
// method call directly in an `else if` condition, so this revision is a
// surgical repair: compute the dead-end flag in a local variable first, then
// branch on that variable.
// 
// Outside spans, the strategy either opens a new constrained span when an
// arithmetic cue was recently observed, or emits a short unconstrained chunk.
// If that chunk naturally emits `<<`, the strategy switches state with
// EnterObservedConstrainedSpan without duplicating the delimiter. Cue tracking
// is lightweight and based only on already-generated tokens.
// 
// Inside spans, parser completeness has priority: complete prefixes are closed
// immediately. Otherwise the strategy checks for a dead-end and repairs with a
// rollback when necessary. For ordinary constrained progress, it uses a
// one-token adaptive constrained step in narrow states or when the caller's
// token budget is 1; otherwise it uses a bounded constrained-symbol step so
// visible growth never exceeds consumed token budget.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained-chunk branch, state remains outside the
//   span unless `stoppedOpen` is true; then EnterObservedConstrainedSpan sets
//   `currentConstrainedOut := []`, which is a valid parser prefix. In the
//   explicit-open branch, OpenConstrainedSpan likewise enters with empty
//   constrained content, preserving validity. In the close branch,
//   CloseConstrainedSpan sets `insideConstrainedOut := false`, so the
//   implication becomes vacuous. In the dead-end-repair branch,
//   RollbackConstrainedSuffix returns a repaired constrained suffix that is a
//   valid parser prefix. In the one-token constrained branch, the adaptive
//   helper returns EOS or a parser-valid next token, and AppendConstrainedToken
//   preserves parser validity. In the symbol branch,
//   ConstrainedSymbolInGenerated returns `symbolOut` that is parser-valid.
// progress: In the unconstrained-chunk branch, `steps` increases by
//   `stepsUsed`, and visible output grows by at most that many tokens; if EOS
//   was consumed but not appended, the inequality only becomes easier. In the
//   explicit-open and close branches, each helper consumes one token-step and
//   appends at most one visible delimiter, so `|generated| <= |generatedPrefix|
//   + steps` is preserved. In the dead-end-repair branch, rollback does not
//   increase visible length and we still increment `steps` by 1, so the bound
//   holds. In the one-token constrained branch, one generation step is charged
//   and at most one visible token is appended. In the symbol branch, `steps`
//   increases by the helper-reported `stepsUsed`, while visible growth is at
//   most the accepted parser-valid prefix length; any rejected suffix tokens or
//   EOS consume budget without increasing visible length, so the bound remains
//   true.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var arithmeticArmed: bool := false;
var cueTokens: seq<Token> := ["=", "+", "-", "*", "/", "total", "sum", "difference", "product", "quotient", "compute", "calculate"];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if arithmeticArmed {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      arithmeticArmed := false;
      steps := steps + 1;
    } else {
      var remainingOutside: nat := maxSteps - steps;
      var chunkBudget: nat := if remainingOutside > 3 then 3 else remainingOutside;
      var chunkedG, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
        lm, prompt, generated, chunkBudget, "<<", eosToken
      );
      generated := chunkedG;
      steps := steps + stepsUsed;

      if stoppedEos {
        break;
      } else if stoppedOpen {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
        arithmeticArmed := false;
      } else {
        var prevEq, foundEq := helpers.LastTokenBefore(generated, "=");
        if foundEq && prevEq != "<<" && prevEq != ">>" {
          arithmeticArmed := true;
        } else {
          var plusSince := helpers.TokensSinceLastOccurrence(generated, "+");
          var minusSince := helpers.TokensSinceLastOccurrence(generated, "-");
          var timesSince := helpers.TokensSinceLastOccurrence(generated, "*");
          var divSince := helpers.TokensSinceLastOccurrence(generated, "/");
          if plusSince <= 2 || minusSince <= 2 || timesSince <= 2 || divSince <= 2 {
            arithmeticArmed := true;
          } else {
            var totalCount := helpers.CountTokenOccurrences(generated, "total");
            var sumCount := helpers.CountTokenOccurrences(generated, "sum");
            if totalCount > 0 || sumCount > 0 {
              arithmeticArmed := true;
            }
          }
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    arithmeticArmed := false;
    steps := steps + 1;
  } else {
    var isDeadEnd := helpers.DeadEndDetection(parser, currentConstrainedOut, 1);
    if isDeadEnd {
      var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
        parser, generated, currentConstrainedOut
      );
      generated := rolledGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := rolledCurrent;
      steps := steps + 1;
    } else {
      var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
      var constrainedPrompt := prompt + stablePrefix;
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

      if validCount <= 10 || stepTokenBudget <= 1 {
        var next := helpers.AdaptiveConstrainedStepWithPenalties(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 4.0, cueTokens, 1.5, 12, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      } else {
        var remainingInside: nat := maxSteps - steps;
        var symbolBudget: nat := if stepTokenBudget == 0 then 1 else if stepTokenBudget > remainingInside then remainingInside else stepTokenBudget;
        var symbolGenerated, symbolOut, hitEos, stepsUsed2 := helpers.ConstrainedSymbolInGenerated(
          lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
        );
        generated := symbolGenerated;
        insideConstrainedOut := true;
        currentConstrainedOut := symbolOut;
        steps := steps + stepsUsed2;
        if hitEos {
          break;
        }
      }
    }
  }
}

cost := steps;
